import json, time, urllib.request, urllib.error, datetime, decimal, sys
BASE='http://localhost:8080'

def get_token():
    req=urllib.request.Request(BASE+'/token', data=b'{}', headers={'Content-Type':'application/json'}, method='POST')
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.load(r)['token']

token=None

def request_json(path, auth=False):
    global token
    while True:
        if auth and token is None:
            token=[REDACTED_SECRET]
        headers={}
        if auth: headers['Authorization']='Bearer '+token
        req=urllib.request.Request(BASE+path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            body=e.read().decode(errors='replace')
            try: info=json.loads(body)
            except Exception: info={}
            if e.code == 401 and auth:
                token=[REDACTED_SECRET]
                continue
            if e.code == 429:
                delay=e.headers.get('Retry-After')
                if delay is None: delay=info.get('retry_after', info.get('wait', info.get('retry_after_seconds')))
                if delay is None:
                    # Honor an explicit duration from the service's message when supplied.
                    import re
                    m=re.search(r'(?:wait|retry)(?: for)?\\s+(\\d+(?:\\.\\d+)?)\\s*(?:seconds|second|secs|sec|s)?', body, re.I)
                    if m: delay=m.group(1)
                if delay is None:
                    print('429 without a stated wait interval:',body,file=sys.stderr); raise
                delay=float(delay)
                print(f'Rate limited on {path}; waiting {delay:g}s',file=sys.stderr,flush=True)
                time.sleep(delay)
                continue
            if e.code >= 500:
                print(f'{e.code} on {path}; retrying in 2s',file=sys.stderr,flush=True); time.sleep(2); continue
            raise RuntimeError(f'{e.code} for {path}: {body}')
        except (urllib.error.URLError, TimeoutError) as e:
            print(f'Network error on {path}: {e}; retrying in 2s',file=sys.stderr,flush=True); time.sleep(2)

orders=[]
seen=set()
duplicates=0
page=1
while True:
    data=request_json(f'/orders?page={page}',auth=True)
    if data.get('page') "'!= page: raise RuntimeError(f'"'Unexpected page response {data.get(\"page\")} for request {page}')
    for item in data['items']:
        oid=item['id']
        if oid in seen:
            duplicates += 1
        else:
            seen.add(oid)
            orders.append(item)
    nxt=data.get('next')
    if nxt is None: break
    # Follow documented next path rather than infer page increments.
    import re
    m=re.search(r'[?&]page=(\\d+)',nxt)
    if not m: raise RuntimeError(f'Unexpected next path: {nxt}')
    page=int(m.group(1))
print(f'Pages fetched: {data[\"page\"]}; unique orders: {len(orders)}; duplicate listings skipped: {duplicates}',file=sys.stderr)

start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
qualifying=[]
for o in orders:
    if o['status'] "'!= '"'shipped': continue
    ts=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
    if start <= ts < end: qualifying.append(o)

customers={}
for o in qualifying:
    cid=o['customer_id']
    if cid not in customers:
        customers[cid]=request_json('/customers/'+str(cid),auth=True)

regions={k:0 for k in ('north','south','east','west')}
for o in qualifying:
    c=customers[o['customer_id']]
    numerator=o['amount_cents']*(100-c['discount_pct'])
    discounted=(numerator+50)//100
    if c['region'] not in regions: raise RuntimeError(f'Unexpected region {c[\"region\"]}')
    regions[c['region']]+=discounted
result={'total_cents':sum(regions.values()),'order_count':len(qualifying),'duplicates_skipped':duplicates,'by_region':regions}
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print(json.dumps(result,sort_keys=True))
print(f'Unique customer records fetched: {len(customers)}; distinct statuses: {sorted({o[\"status\"] for o in orders})}',file=sys.stderr)
